/** The settings unknown case is a GROUP, not a top-level key. */
function unknownInstance(spec: TypeSpec): Record<string, unknown> {
  if (spec.type === 'settings') {
    return {
      settings: { general: { theme: 'dark' }, experimental: { agentSidebar: true } },
      fieldClocks: { 'general.theme': CLOCK, 'experimental.agentSidebar': CLOCK }
    }
  }
  return { ...spec.valid, [spec.unknownKey]: spec.unknownValue }
}

export function buildPayloadSchemas(): Record<string, unknown> {
  const groups = SPECS.map((spec) => {
    const unknown = unknownInstance(spec)
    const unknownJson = JSON.stringify(unknown)
    const parsedUnknown = spec.schema.parse(unknown) as Record<string, unknown>
    return {
      type: spec.type,
      cases: [
        {
          name: `${spec.type}: valid, every modelled field populated`,
          payload: spec.valid,
          expectedParsed: spec.schema.parse(spec.valid),
          pins: "the projector's field list against the payload's"
        },
        {
          name: `${spec.type}: boundary — empty strings, empty arrays, optionals absent`,
          payload: spec.boundary,
          expectedParsed: spec.schema.parse(spec.boundary),
          pins: 'absent and empty stay distinct across the round trip'
        },
        {
          name: `${spec.type}: an unknown field a newer client wrote`,
          payload: unknown,
          expectedParsed: parsedUnknown,
          strippedByParse:
            spec.type === 'settings'
              ? ['settings.experimental']
              : Object.keys(unknown).filter((k) => !(k in parsedUnknown)),
          pins: 'THE SC-014 CASE: Zod strips the key from the PARSED object, and the stored payload string must not change'
        },
        {
          name: `${spec.type}: verbatim round trip of the unknown-field instance`,
          storedPayloadJson: unknownJson,
          expectedPushedPayloadJson: unknownJson,
          pins: 'the exact bytes that must come back out. An implementation that deserialises into a struct and re-serialises fails here'
        }
      ]
    }
  })

  return {
    meta: meta({
      class: 'payload-schemas',
      chapter: 'docs/protocol/13-payload-schemas.md',
      schemas: 'packages/contracts/src/sync-payloads.ts, packages/contracts/src/settings-sync.ts',
      subscribedTypes: SPECS.map((s) => s.type),
      obligation:
        'a payload schema is a READER over a preserved string, never the storage shape (FR-033)',
      caseCount: groups.reduce((n, g) => n + g.cases.length, 0)
    }),
    groups
  }
}
